/* Custom unsigned binary search to avoid LVGL v9.5 lv_utils_bsearch int32_t comparison bug when rcp >= 0x4E00 */
static uint32_t misans_get_glyph_dsc_id(const lv_font_t * font, uint32_t letter)
{
    if(letter == '\0') return 0;

    const lv_font_fmt_txt_dsc_t * fdsc = (const lv_font_fmt_txt_dsc_t *)font->dsc;

    for(uint16_t i = 0; i < fdsc->cmap_num; i++) {
        uint32_t rcp = letter - fdsc->cmaps[i].range_start;
        if(rcp >= fdsc->cmaps[i].range_length) continue;

        if(fdsc->cmaps[i].type == LV_FONT_FMT_TXT_CMAP_FORMAT0_TINY) {
            return fdsc->cmaps[i].glyph_id_start + rcp;
        }
        else if(fdsc->cmaps[i].type == LV_FONT_FMT_TXT_CMAP_SPARSE_TINY) {
            const uint16_t * ulist = fdsc->cmaps[i].unicode_list;
            uint32_t lo = 0;
            uint32_t hi = fdsc->cmaps[i].list_length;
            while(lo < hi) {
                uint32_t mid = lo + ((hi - lo) >> 1);
                uint16_t v = ulist[mid];
                if(v == (uint16_t)rcp) {
                    return fdsc->cmaps[i].glyph_id_start + mid;
                } else if(v < (uint16_t)rcp) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            return 0;
        }
    }
    return 0;
}

static bool misans_get_glyph_dsc_cb(const lv_font_t * font, lv_font_glyph_dsc_t * dsc_out, uint32_t unicode_letter,
                                    uint32_t unicode_letter_next)
{
    (void)unicode_letter_next;
    bool is_tab = (unicode_letter == '\t');
    if(is_tab) {
        unicode_letter = ' ';
    }
    const lv_font_fmt_txt_dsc_t * fdsc = (const lv_font_fmt_txt_dsc_t *)font->dsc;
    uint32_t gid = misans_get_glyph_dsc_id(font, unicode_letter);
    if(!gid) return false;

    const lv_font_fmt_txt_glyph_dsc_t * gdsc = &fdsc->glyph_dsc[gid];
    uint32_t adv_w = gdsc->adv_w;
    if(is_tab) adv_w *= 2;
    adv_w = (adv_w + (1 << 3)) >> 4;

    dsc_out->adv_w = adv_w;
    dsc_out->box_h = gdsc->box_h;
    dsc_out->box_w = is_tab ? (gdsc->box_w * 2) : gdsc->box_w;
    dsc_out->ofs_x = gdsc->ofs_x;
    dsc_out->ofs_y = gdsc->ofs_y;
    dsc_out->stride = 0;
    dsc_out->format = (uint8_t)fdsc->bpp;
    dsc_out->is_placeholder = false;
    dsc_out->gid.index = gid;
    return true;
}

